"""Glossary lookup for Rapidly Deployable Smart Cities."""

GLOSSARY = {
    "digital twin": "a live model of the building fed by sensors",
    "energy-positive": "generating more energy over a year than consumed",
    "seismic design": "engineering structures to survive earthquakes",
    "modular construction": "building from factory-made volumetric modules",
    "district energy": "shared heating and cooling serving many buildings",
    "universal design": "spaces usable by people of all abilities",
}

def lookup(term):
    key = term.strip().lower()
    for k, v in GLOSSARY.items():
        if k.lower() == key:
            return k + ": " + v
    cands = [k for k in GLOSSARY if key in k.lower()]
    return ("Did you mean: " + ", ".join(cands)) if cands else "No entry."


if __name__ == "__main__":
    print("Rapidly Deployable Smart Cities glossary — %d terms" % len(GLOSSARY))
    for t in list(GLOSSARY)[:3]:
        print("-", lookup(t))

"""Piece model: Structural System — part of the Rapidly Deployable Smart Cities system."""
import random

class RapidlyDeployableSmartCitiesPiece1StructuralSystem:
    """Models the Structural System piece: specification check and behavior sample."""

    SPEC = {"piece": "Structural System", "interfaces": 3, "redundancy": 2}

    def __init__(self, seed=11):
        self.rng = random.Random(seed)

    def spec_check(self):
        """Verify the piece meets its interface contract."""
        results = {}
        for i in range(self.SPEC["interfaces"]):
            # simulated conformance measurement around a nominal value
            measured = 1.0 + self.rng.uniform(-0.04, 0.04)
            results["interface_%d" % i] = round(measured, 3)
        ok = all(0.94 <= v <= 1.06 for v in results.values())
        return {"pass": ok, "measurements": results}

    def simulate(self, cycles=24):
        """Sample operating behavior over a number of cycles."""
        health = 1.0
        for _ in range(cycles):
            stress = self.rng.uniform(0.0, 0.06)
            health = max(0.0, health - stress * 0.2)
            health = min(1.0, health + 0.05)  # recovery / maintenance
        return {"cycles": cycles, "health": round(health, 3),
                "redundancy_ok": health > 0.5}


if __name__ == "__main__":
    m = RapidlyDeployableSmartCitiesPiece1StructuralSystem(seed=11)
    sc = m.spec_check()
    sm = m.simulate(24)
    print("Structural System — Rapidly Deployable Smart Cities")
    print("spec check pass:", sc["pass"], "| measurements:", sc["measurements"])
    print("health after", sm["cycles"], "cycles:", sm["health"])

